import heapq

def shortest_path(edges, start, end):
    # マイナスエッジのチェック
    for u, v, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights must not be negative.")

    # start と end が同じ場合の処理
    if start == end:
        return (0, [start])

    # グラフの構築 (Adjacency list)
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, weight in edges:
        graph[u].append((v, weight))

    # ダイクストラ法の実装
    # 優先度付きキューには (現在の総距離, 現在のノード, 経路のリスト) を格納
    pq = [(0, start, [start])]

    # 訪れたノードの最小距離を記録する辞書
    distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # 目的地に到達した場合
        if current_node == end:
            return (current_distance, path)

        # 記録されている最短距離よりも長い場合はスキップ
        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # より短い経路が見つかった場合
            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # 経路が存在しない場合
    return (None, None)

# --- 使用例 ---
if __name__ == "__main__":
    edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
    print(shortest_path(edges, "A", "C"))  # 出力: (3, ['A', 'B', 'C'])
    print(shortest_path(edges, "A", "A"))  # 出力: (0, ['A'])
    print(shortest_path(edges, "A", "D"))  # 出力: (None, None)

    try:
        shortest_path([("A", "B", -1)], "A", "B")
    except ValueError as e:
        print(e)  # 出力: Edge weights must not be negative.
